package org.apache.commons.math.optimization.univariate;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Comparator;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.optimization.ConvergenceChecker;
import org.apache.commons.math.optimization.GoalType;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.FunctionEvaluationException;
import org.apache.commons.math3.optimization.univariate.GoalType.MAXIMIZE;
import org.apache.commons.math3.optimization.univariate.GoalType.MINIMIZE;
import org.apache.commons.math3.random.JDKRandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for MultiStartUnivariateRealOptimizer.optimize(FUNC, GoalType, double, double)
 */
public class MultiStartUnivariateRealOptimizer_optimize_TriageGen0Test {

    private BaseUnivariateRealOptimizer<UnivariateFunction> optimizer;
    private MultiStartUnivariateRealOptimizer multiStartOptimizer;
    private final int starts = 5;
    private final JDKRandomGenerator randomGenerator = new JDKRandomGenerator();

    @Before
    public void setUp() {
        // Using a simple BrentOptimizer as the base optimizer
        optimizer = new BrentOptimizer();
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(optimizer, starts, randomGenerator);
    }

    @Test
    public void testOptimizeMinimize() throws FunctionEvaluationException {
        // f(x) = (x - 2)^2 + 3. Minimum is at x = 2, value = 3
        UnivariateFunction f = x -> Math.pow(x - 2.0, 2) + 3.0;
        double min = 0.0;
        double max = 5.0;

        UnivariateRealPointValuePair result = multiStartOptimizer.optimize(f, GoalType.MINIMIZE, min, max);

        assertNotNull(result);
        assertEquals("The point should be close to 2.0", 2.0, result.getPoint(), 1e-6);
        assertEquals("The value should be close to 3.0", 3.0, result.getValue(), 1e-6);
    }

    @Test
    public void testOptimizeMaximize() throws FunctionEvaluationException {
        // f(x) = -(x - 3)^2 + 10. Maximum is at x = 3, value = 10
        UnivariateFunction f = x -> -Math.pow(x - 3.0, 2) + 10.0;
        double min = 0.0;
        double max = 5.0;

        UnivariateRealPointValuePair result = multiStartOptimizer.optimize(f, GoalType.MAXIMIZE, min, max);

        assertNotNull(result);
        assertEquals("The point should be close to 3.0", 3.0, result.getPoint(), 1e-6);
        assertEquals("The value should be close to 10.0", 10.0, result.getValue(), 1e-6);
    }

    @Test
    public void testOptimizeWithLargeRange() throws FunctionEvaluationException {
        // f(x) = x. Min at -100, Max at 100
        UnivariateFunction f = x -> x;
        double min = -100.0;
        double max = 100.0;

        UnivariateRealPointValuePair minResult = multiStartOptimizer.optimize(f, GoalType.MINIMIZE, min, max);
        UnivariateRealPointValuePair maxResult = multiStartOptimizer.optimize(f, GoalType.MAXIMIZE, min, max);

        assertEquals(-100.0, minResult.getPoint(), 1e-6);
        assertEquals(100.0, maxResult.getPoint(), 1e-6);
    }

    @Test(expected = FunctionEvaluationException.class)
    public void testOptimizeThrowsException() throws FunctionEvaluationException {
        // Function that throws exception
        UnivariateFunction f = x -> {
            if (x > 2.0) {
                throw new FunctionEvaluationException(new RuntimeException("Error"));
            }
            return x;
        };

        // This should trigger the exception during optimization process
        multiStartOptimizer.optimize(f, GoalType.MINIMIZE, 0.0, 5.0);
    }

    @Test
    public void testGetOptimaAfterOptimization() throws FunctionEvaluationException {
        UnivariateFunction f = x -> Math.pow(x - 1.0, 2);
        multiStartOptimizer.optimize(f, GoalType.MINIMIZE, 0.0, 2.0);

        UnivariateRealPointValuePair[] optima = multiStartOptimizer.getOptima();
        assertNotNull(optima);
        assertTrue(optima.length > 0);
    }

    @Test
    public void testGetEvaluations() throws FunctionEvaluationException {
        UnivariateFunction f = x -> x * x;
        multiStartOptimizer.optimize(f, GoalType.MINIMIZE, -1.0, 1.0);

        int evaluations = multiStartOptimizer.getEvaluations();
        assertTrue("Evaluations should be greater than 0", evaluations > 0);
    }
}
